import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const mountainBreakerScenarios=['mountain-base','mountain-lia','mountain-lancelot','mountain-lancelot-ii','mountain-relative','breaker-base'] as const;
export type MountainBreakerScenario=typeof mountainBreakerScenarios[number];
export function isMountainBreakerScenario(name:string):name is MountainBreakerScenario{return (mountainBreakerScenarios as readonly string[]).includes(name);}
export function mountainBreakerMode(name:MountainBreakerScenario){const breaker=name==='breaker-base',lance=name.startsWith('mountain-lancelot'),dedicated=lance||name==='mountain-lia';return {card:breaker?'a2-p12-r1c2':'a2-p12-r1c1',owner:lance?(name.endsWith('-ii')?'聖騎士ランスロット2':'聖騎士ランスロット'):'リーア姫',dedicated,effect:lance?5:4,damage:breaker?5:lance?6:dedicated?5:4,far:breaker};}
export function makeMountainBreakerScenario(name:MountainBreakerScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;prepared?:boolean;follower?:string}={}){
 const m=mountainBreakerMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??m.owner);assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.warrior_level=20+(options.level??4)-stats.warrior_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,m.card),advance=takeCard(s,a,'a2-p24-r1c2'),prayer=takeCard(s,a,'必勝の祈り'),maai=takeCard(s,b,'a2-p07-r1c1'),fate=takeCard(s,c,'命運凶変'),follower=options.follower??(name==='mountain-relative'?'悪魔':undefined),guard=follower?takeCard(s,b,follower):null;for(const id of [a,b,c,d])trimHand(s,id,card,advance,prayer,maai,fate,...(guard?[guard]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`MOUNTAIN_BREAKER_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('MOUNTAIN_BREAKER_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('MOUNTAIN_BREAKER_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(!m.far&&options.prepared!==false){act(a,{type:'APPROACH',targetId:b,cardInstanceId:advance});for(let n=0;n<100&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}return s;
}
